from django.http import HttpResponse
from django.conf import settings
import os

def getResource(request):
    '''
    Get username and date from the request, then
    send the file to the user by creating path by the username and date.
    '''
    if request.method == 'GET':
        username = request.GET.get('username')
        date = request.GET.get('date')

        if not username or not date:
            return HttpResponse("Missing username or date", status=400)

        # Create a directory path based on username and date
        directory_path = os.path.join(settings.MEDIA_ROOT, f"{username}_{date}")

        # Check if the directory exists, if not, create it
        if not os.path.exists(directory_path):
            os.makedirs(directory_path)

        # Assuming the file to be sent is named 'file.txt' in the MEDIA_ROOT
        file_path = os.path.join(settings.MEDIA_ROOT, 'file.txt')

        if os.path.exists(file_path):
            with open(file_path, 'rb') as file:
                response = HttpResponse(file.read(), content_type='application/octet-stream')
                response['Content-Disposition'] = f'attachment; filename="{os.path.basename(file_path)}"'
                return response
        else:
            return HttpResponse("File not found", status=404)
    else:
        return HttpResponse("Invalid request method", status=405)
