import xml.sax

def get_root():
    '''
    Create an XML parser,
    parse the file 'resources/config.xml' and return the parsed result.
    '''
    class ConfigHandler(xml.sax.ContentHandler):
        def __init__(self):
            self.root = None

        def startElement(self, name, attrs):
            if self.root is None:
                self.root = {'tag': name, 'attrs': attrs, 'children': []}

        def endElement(self, name):
            pass

        def characters(self, content):
            if self.root is not None:
                self.root['children'].append({'tag': name, 'content': content})

    parser = xml.sax.make_parser()
    parser.setContentHandler(ConfigHandler())
    parser.parse('resources/config.xml')
    return ConfigHandler().root
