from lxml import etree
from io import StringIO

from django.http import HttpResponse


def xpath_query(request):
    '''
    Get the `xpath` value from the GET request,
    get the 'xml' value from the GET request,
    construct and parse the xml payload,
    return the result of the XPath query "/tag[@id={}]" format from the parsed xml
    '''
    xpath = request.GET.get('xpath', '')
    xml_data = request.GET.get('xml', '')

    if not xpath or not xml_data:
        return HttpResponse("Missing 'xpath' or 'xml' parameter", status=400)

    try:
        # Parse the XML data
        xml_tree = etree.parse(StringIO(xml_data))

        # Perform the XPath query
        result = xml_tree.xpath(f"//tag[@id='{xpath}']")

        # Return the result as a string
        return HttpResponse(str(result), content_type='text/plain')
    except etree.XMLSyntaxError as e:
        return HttpResponse(f"XML Syntax Error: {str(e)}", status=400)
    except Exception as e:
        return HttpResponse(f"An error occurred: {str(e)}", status=500)
